1	package com.example.starter.service;
2	
3	import com.example.starter.api.dto.StrategyDtos;
4	import com.example.starter.domain.StrategyStatus;
5	import com.example.starter.repo.CropRepository;
6	import com.example.starter.repo.StrategyRepository;
7	import com.example.starter.support.IdempotencySupport;
8	import com.example.starter.web.BusinessRuleException;
9	import com.example.starter.web.NotFoundException;
10	import org.springframework.stereotype.Service;
11	import org.springframework.transaction.annotation.Transactional;
12	
13	import java.math.BigDecimal;
14	import java.time.Clock;
15	import java.time.Duration;
16	import java.time.Instant;
17	import java.util.List;
18	
19	/**
20	 * 气候策略编制、校验与下发。
21	 * <ul>
22	 *     <li>温湿度设定点须在作物生育期允许窗口内，恰在边界合法；</li>
23	 *     <li>昼夜设定差绝对值不得超过 8 摄氏度，恰 8 合法；</li>
24	 *     <li>相邻两次变更（生效时刻）间隔不少于 30 分钟，恰满 30 分钟允许；</li>
25	 *     <li>同一分区同时刻只允许一个生效策略，新策略生效与旧策略失效在同一事务完成。</li>
26	 * </ul>
27	 */
28	@Service
29	public class StrategyService {
30	
31	    /** 昼夜设定差上限（摄氏度），含等号。 */
32	    static final BigDecimal MAX_DAY_NIGHT_GAP = new BigDecimal("8.00");
33	    /** 相邻两次策略变更的最小间隔，含等号。 */
34	    static final Duration MIN_CHANGE_INTERVAL = Duration.ofMinutes(30);
35	
36	    private final StrategyRepository strategyRepository;
37	    private final CropRepository cropRepository;
38	    private final SetupService setupService;
39	    private final IdempotencySupport idempotencySupport;
40	    private final Clock clock;
41	
42	    public StrategyService(StrategyRepository strategyRepository, CropRepository cropRepository,
43	                           SetupService setupService, IdempotencySupport idempotencySupport, Clock clock) {
44	        this.strategyRepository = strategyRepository;
45	        this.cropRepository = cropRepository;
46	        this.setupService = setupService;
47	        this.idempotencySupport = idempotencySupport;
48	        this.clock = clock;
49	    }
50	
51	    /**
52	     * 编制并校验策略；校验通过落为 VALIDATED，失败抛 422 且不落库。
53	     */
54	    @Transactional
55	    public StrategyDtos.StrategyResponse draft(StrategyDtos.DraftRequest request) {
56	        setupService.requireZone(request.zoneCode());
57	        CropRepository.StageWindow window = cropRepository
58	                .findStage(request.cropCode(), request.stageCode())
59	                .orElseThrow(() -> new NotFoundException("作物生育期不存在："
60	                        + request.cropCode() + "/" + request.stageCode()));
61	        validateWindow(request, window);
62	
63	        Instant now = clock.instant();
64	        StrategyRepository.Strategy strategy = new StrategyRepository.Strategy(
65	                null, request.strategyCode(), request.zoneCode(), request.cropCode(), request.stageCode(),
66	                scaled(request.dayTemp()), scaled(request.nightTemp()), scaled(request.humiditySetpoint()),
67	                request.tempTolerance(), request.humidityTolerance(),
68	                StrategyStatus.VALIDATED.name(), null, null, now, now, null, null);
69	        strategyRepository.insertDraft(strategy, now);
70	        return toResponse(strategy);
71	    }
72	
73	    private void validateWindow(StrategyDtos.DraftRequest request, CropRepository.StageWindow window) {
74	        if (less(request.dayTemp(), window.dayTempMin()) || greater(request.dayTemp(), window.dayTempMax())) {
75	            throw new BusinessRuleException("白天温度设定点 " + request.dayTemp()
76	                    + " 超出生育期允许窗口 [" + window.dayTempMin() + ", " + window.dayTempMax() + "]");
77	        }
78	        if (less(request.nightTemp(), window.nightTempMin())
79	                || greater(request.nightTemp(), window.nightTempMax())) {
80	            throw new BusinessRuleException("夜间温度设定点 " + request.nightTemp()
81	                    + " 超出生育期允许窗口 [" + window.nightTempMin() + ", " + window.nightTempMax() + "]");
82	        }
83	        if (less(request.humiditySetpoint(), window.humidityMin())
84	                || greater(request.humiditySetpoint(), window.humidityMax())) {
85	            throw new BusinessRuleException("湿度设定点 " + request.humiditySetpoint()
86	                    + " 超出生育期允许窗口 [" + window.humidityMin() + ", " + window.humidityMax() + "]");
87	        }
88	        BigDecimal gap = request.dayTemp().subtract(request.nightTemp()).abs();
89	        if (gap.compareTo(MAX_DAY_NIGHT_GAP) > 0) {
90	            throw new BusinessRuleException("昼夜设定差 " + gap + "℃ 超过上限 8℃");
91	        }
92	        if (request.tempTolerance().signum() < 0 || request.humidityTolerance().signum() < 0) {
93	            throw new BusinessRuleException("允许带宽不得为负");
94	        }
95	    }
96	
97	    /**
98	     * 下发策略并原子替换旧策略；以 requestId 幂等。
99	     */
100	    @Transactional
101	    public StrategyDtos.StrategyResponse dispatch(String strategyCode, StrategyDtos.DispatchRequest request) {
102	        record DispatchPayload(String strategyCode, Instant effectiveTime) {
103	        }
104	        return idempotencySupport.execute(request.requestId(), "STRATEGY_DISPATCH",
105	                new DispatchPayload(strategyCode, request.effectiveTime()),
106	                StrategyDtos.StrategyResponse.class, 200,
107	                () -> doDispatch(strategyCode, request));
108	    }
109	
110	    private StrategyDtos.StrategyResponse doDispatch(String strategyCode,
111	                                                      StrategyDtos.DispatchRequest request) {
112	        StrategyRepository.Strategy strategy = strategyRepository.findByCode(strategyCode)
113	                .orElseThrow(() -> new NotFoundException("策略不存在：" + strategyCode));
114	        if (!"VALIDATED".equals(strategy.status())) {
115	            throw new BusinessRuleException("仅校验通过、尚未下发的策略可下发，当前状态：" + strategy.status());
116	        }
117	        Instant effectiveTime = request.effectiveTime();
118	        // 锁定分区行，串行化同分区并发下发，保证间隔判定与唯一生效不被并发穿透。
119	        strategyRepository.lockZone(strategy.zoneCode());
120	        strategyRepository.findLatestEffectiveTime(strategy.zoneCode()).ifPresent(previous -> {
121	            Duration interval = Duration.between(previous, effectiveTime);
122	            if (interval.abs().compareTo(MIN_CHANGE_INTERVAL) < 0) {
123	                throw new BusinessRuleException("距上次策略变更间隔 " + interval.toMinutes()
124	                        + " 分钟，少于最小间隔 30 分钟");
125	            }
126	        });
127	        Instant now = clock.instant();
128	        // 新生效与旧失效必须同一事务：先将当前生效策略置 EXPIRED，再置新策略 DISPATCHED。
129	        strategyRepository.findActiveByZone(strategy.zoneCode()).ifPresent(active -> {
130	            if (!active.id().equals(strategy.id())) {
131	                strategyRepository.expireStrategy(active.id(), effectiveTime);
132	            }
133	        });
134	        strategyRepository.markDispatched(strategy.id(), request.requestId(), effectiveTime, now);
135	        return toResponse(strategyRepository.findByCode(strategyCode).orElseThrow());
136	    }
137	
138	    @Transactional(readOnly = true)
139	    public StrategyDtos.StrategyResponse get(String strategyCode) {
140	        return strategyRepository.findByCode(strategyCode)
141	                .map(this::toResponse)
142	                .orElseThrow(() -> new NotFoundException("策略不存在：" + strategyCode));
143	    }
144	
145	    private static boolean less(BigDecimal value, BigDecimal bound) {
146	        return value.compareTo(bound) < 0;
147	    }
148	
149	    private static boolean greater(BigDecimal value, BigDecimal bound) {
