26	        String canonical;
27	        try {
28	            canonical = objectMapper.writeValueAsString(businessPayload);
29	        } catch (JsonProcessingException e) {
30	            throw new IllegalStateException("幂等指纹序列化失败", e);
31	        }
32	        MessageDigest digest;
