1	package com.example.starter.service;
2	
3	import com.example.starter.api.dto.EvaluationDtos;
4	import com.example.starter.repo.BudgetRepository;
5	import com.example.starter.repo.CommandRepository;
6	import com.example.starter.repo.EvaluationRepository;
7	import com.example.starter.repo.ReadingRepository;
8	import com.example.starter.repo.StrategyRepository;
9	import com.example.starter.web.NotFoundException;
10	import com.fasterxml.jackson.core.JsonProcessingException;
11	import com.fasterxml.jackson.core.type.TypeReference;
12	import com.fasterxml.jackson.databind.ObjectMapper;
13	import org.springframework.dao.DuplicateKeyException;
14	import org.springframework.stereotype.Service;
15	import org.springframework.transaction.annotation.Transactional;
16	
17	import java.math.BigDecimal;
18	import java.time.Clock;
19	import java.time.Instant;
20	import java.time.LocalDate;
21	import java.util.ArrayList;
22	import java.util.LinkedHashMap;
23	import java.util.List;
24	import java.util.Map;
25	
26	/**
27	 * 日评估服务（UTC 日界）：
28	 * <ul>
29	 *     <li>封存（SEALED）为终态：重复封存幂等返回首次结果，并标记 replayed=true；</li>
30	 *     <li>封存后到达的读数由读数服务隔离为迟到事件，不影响已封存结果；</li>
31	 *     <li>输出设定达成率与按指令类型汇总的能耗明细，全部基于读数/指令/预算表现算，可复算。</li>
32	 * </ul>
33	 */
34	@Service
35	public class EvaluationService {
36	
37	    private static final String SEALED = "SEALED";
38	
39	    private final EvaluationRepository evaluationRepository;
40	    private final ReadingRepository readingRepository;
41	    private final StrategyRepository strategyRepository;
42	    private final CommandRepository commandRepository;
43	    private final BudgetRepository budgetRepository;
44	    private final SetupService setupService;
45	    private final ObjectMapper objectMapper;
46	    private final Clock clock;
47	
48	    public EvaluationService(EvaluationRepository evaluationRepository, ReadingRepository readingRepository,
49	                             StrategyRepository strategyRepository, CommandRepository commandRepository,
50	                             BudgetRepository budgetRepository, SetupService setupService,
51	                             ObjectMapper objectMapper, Clock clock) {
52	        this.evaluationRepository = evaluationRepository;
53	        this.readingRepository = readingRepository;
54	        this.strategyRepository = strategyRepository;
55	        this.commandRepository = commandRepository;
56	        this.budgetRepository = budgetRepository;
57	        this.setupService = setupService;
58	        this.objectMapper = objectMapper;
59	        this.clock = clock;
60	    }
61	
62	    @Transactional
63	    public EvaluationDtos.EvaluationResponse seal(EvaluationDtos.EvaluationRequest request) {
64	        setupService.requireZone(request.zoneCode());
65	        var existing = evaluationRepository.find(request.zoneCode(), request.evalDate());
66	        if (existing.isPresent()) {
67	            // 封存终态：重复封存幂等成功，返回首次结果。
68	            return toResponse(existing.get(), true);
69	        }
70	        Computed computed = compute(request.zoneCode(), request.evalDate());
71	        Instant now = clock.instant();
72	        EvaluationRepository.Evaluation evaluation = new EvaluationRepository.Evaluation(
73	                null, request.zoneCode(), request.evalDate(), SEALED,
74	                computed.inBandCount(), computed.totalCount(), computed.achievementRate(),
75	                computed.budgetKwh(), computed.consumedKwh(), computed.energyDetailJson(), now, now);
76	        try {
77	            evaluationRepository.insert(evaluation);
78	        } catch (DuplicateKeyException e) {
79	            // 并发封存：唯一约束保证仅一条成功，败者幂等返回胜者结果。
80	            EvaluationRepository.Evaluation winner =
81	                    evaluationRepository.find(request.zoneCode(), request.evalDate()).orElseThrow();
82	            return toResponse(winner, true);
83	        }
84	        return toResponse(
85	                evaluationRepository.find(request.zoneCode(), request.evalDate()).orElseThrow(), false);
86	    }
87	
88	    @Transactional(readOnly = true)
89	    public EvaluationDtos.EvaluationResponse get(String zoneCode, LocalDate date) {
90	        return evaluationRepository.find(zoneCode, date)
91	                .map(e -> toResponse(e, false))
92	                .orElseThrow(() -> new NotFoundException("当日评估不存在：" + zoneCode + " " + date));
93	    }
94	
95	    /**
96	     * 现算达成率与能耗明细。读数是否在带内，按该采样时刻生效策略的设定带逐点判定；边界视为带内。
97	     */
98	    private Computed compute(String zoneCode, LocalDate evalDate) {
99	        List<ReadingRepository.Reading> readings = readingRepository.findByUtcDate(zoneCode, evalDate);
100	        int inBand = 0;
101	        for (ReadingRepository.Reading r : readings) {
102	            StrategyRepository.Strategy strategy =
103	                    strategyRepository.findEffectiveAt(zoneCode, r.sampleTime()).orElse(null);
104	            if (strategy != null && !ReadingService.isOutOfBand(strategy, r)) {
105	                inBand++;
106	            }
107	        }
108	        int total = readings.size();
109	        BigDecimal rate = total == 0
110	                ? BigDecimal.ZERO.setScale(4)
111	                : BigDecimal.valueOf(inBand).divide(BigDecimal.valueOf(total), 4,
112	                        java.math.RoundingMode.HALF_UP);
113	
114	        Map<String, Aggregate> aggregates = new LinkedHashMap<>();
115	        BigDecimal consumed = BigDecimal.ZERO.setScale(3);
116	        for (CommandRepository.Command c : commandRepository.findByUtcDate(zoneCode, evalDate)) {
117	            Aggregate aggregate = aggregates.computeIfAbsent(c.commandType(), k -> new Aggregate());
118	            aggregate.commandCount++;
119	            aggregate.energyKwh = aggregate.energyKwh.add(c.energyKwh());
120	            consumed = consumed.add(c.energyKwh());
121	        }
122	        List<EvaluationDtos.EnergyItem> items = new ArrayList<>();
123	        aggregates.forEach((type, agg) -> items.add(
124	                new EvaluationDtos.EnergyItem(type, agg.commandCount, agg.energyKwh.setScale(3))));
125	
126	        BigDecimal budgetKwh = budgetRepository.find(zoneCode, evalDate)
127	                .map(BudgetRepository.Budget::budgetKwh)
128	                .orElse(null);
129	        return new Computed(inBand, total, rate, budgetKwh, consumed.setScale(3), writeJson(items));
130	    }
131	
132	    private String writeJson(List<EvaluationDtos.EnergyItem> items) {
133	        try {
134	            return objectMapper.writeValueAsString(items);
135	        } catch (JsonProcessingException e) {
136	            throw new IllegalStateException("能耗明细序列化失败", e);
137	        }
138	    }
139	
140	    private List<EvaluationDtos.EnergyItem> readJson(String json) {
141	        try {
142	            return objectMapper.readValue(json, new TypeReference<List<EvaluationDtos.EnergyItem>>() {
143	            });
144	        } catch (JsonProcessingException e) {
145	            throw new IllegalStateException("能耗明细反序列化失败", e);
146	        }
147	    }
148	
149	    private EvaluationDtos.EvaluationResponse toResponse(EvaluationRepository.Evaluation e, boolean replayed) {
150	        return new EvaluationDtos.EvaluationResponse(e.id(), e.zoneCode(), e.evalDate(), e.status(),
151	                e.inBandCount(), e.totalCount(), e.achievementRate(), e.budgetKwh(), e.consumedKwh(),
152	                readJson(e.energyDetailJson()), e.sealedAt(), replayed);
153	    }
154	
155	    private static final class Aggregate {
156	        private int commandCount;
157	        private BigDecimal energyKwh = BigDecimal.ZERO.setScale(3);
158	    }
159	
160	    private record Computed(int inBandCount, int totalCount, BigDecimal achievementRate,
161	                            BigDecimal budgetKwh, BigDecimal consumedKwh, String energyDetailJson) {
162	    }
163	}
