3	import com.example.starter.AbstractIntegrationTest;
4	import com.example.starter.api.dto.StrategyDtos;
5	import com.example.starter.repo.StrategyRepository;
6	import com.example.starter.web.BusinessRuleException;
7	import com.example.starter.web.ConflictException;
8	import org.junit.jupiter.api.BeforeEach;
9	import org.junit.jupiter.api.DisplayName;
10	import org.junit.jupiter.api.Test;
11	import org.springframework.beans.factory.annotation.Autowired;
12	
13	import java.time.Instant;
14	import java.util.List;
15	import java.util.concurrent.CountDownLatch;
16	import java.util.concurrent.ExecutorService;
17	import java.util.concurrent.Executors;
18	import java.util.concurrent.Future;
19	import java.util.concurrent.TimeUnit;
20	
21	import static org.assertj.core.api.Assertions.assertThat;
22	import static org.assertj.core.api.Assertions.assertThatThrownBy;
23	
24	/**
25	 * 下发：变更间隔恰 30 分钟允许、新旧策略同事务原子切换、requestId 幂等与并发唯一生效。
26	 */
27	class StrategyDispatchTest extends AbstractIntegrationTest {
28	
29	    private static final Instant T0 = Instant.parse("2026-01-02T00:00:00Z");
30	
31	    @Autowired
32	    private StrategyRepository strategyRepository;
33	
34	    @BeforeEach
35	    void setUp() {
36	        seedZone();
37	        seedCrop();
38	    }
39	
40	    @Test
41	    @DisplayName("相邻生效间隔恰满 30 分钟允许，少 1 秒被拒绝")
42	    void intervalExactlyThirtyMinutesAllowed() {
43	        draftStrategy("S1", "24.00", "18.00", "70.00", "0.5", "5");
44	        dispatch("S1", "REQ-D1", T0);
45	
46	        draftStrategy("S2", "25.00", "17.00", "70.00", "0.5", "5");
47	        assertThatThrownBy(() -> dispatch("S2", "REQ-D2-EARLY", T0.plusSeconds(29 * 60 + 59)))
48	                .isInstanceOf(BusinessRuleException.class)
49	                .hasMessageContaining("30 分钟");
50	
51	        // 同键异参一律 409：失败请求的 requestId 换时刻重提仍冲突，须换新键。
52	        assertThatThrownBy(() -> dispatch("S2", "REQ-D2-EARLY", T0.plusSeconds(30 * 60)))
53	                .isInstanceOf(ConflictException.class);
54	
55	        StrategyDtos.StrategyResponse exact = dispatch("S2", "REQ-D2", T0.plusSeconds(30 * 60));
56	        assertThat(exact.status()).isEqualTo("DISPATCHED");
57	        assertThat(exact.effectiveTime()).isEqualTo(T0.plusSeconds(30 * 60));
58	    }
59	
60	    @Test
61	    @DisplayName("新策略生效与旧策略失效在同一事务完成：旧 EXPIRED、新 DISPATCHED")
62	    void switchIsAtomic() {
63	        draftStrategy("S1", "24.00", "18.00", "70.00", "0.5", "5");
64	        draftStrategy("S2", "25.00", "17.00", "70.00", "0.5", "5");
65	        dispatch("S1", "REQ-D1", T0);
66	        dispatch("S2", "REQ-D2", T0.plusSeconds(30 * 60));
67	
68	        StrategyRepository.Strategy oldOne = strategyRepository.findByCode("S1").orElseThrow();
69	        StrategyRepository.Strategy newOne = strategyRepository.findByCode("S2").orElseThrow();
70	        assertThat(oldOne.status()).isEqualTo("EXPIRED");
71	        assertThat(oldOne.expiredAt()).isEqualTo(T0.plusSeconds(30 * 60));
72	        assertThat(newOne.status()).isEqualTo("DISPATCHED");
73	        assertThat(strategyRepository.findActiveByZone(ZONE)).isPresent()
74	                .get().extracting(StrategyRepository.Strategy::strategyCode).isEqualTo("S2");
75	    }
76	
77	    @Test
78	    @DisplayName("同 requestId 同参数重放返回首次结果，不重复失效其他策略")
79	    void sameRequestReplayReturnsFirstResult() {
80	        draftStrategy("S1", "24.00", "18.00", "70.00", "0.5", "5");
81	        StrategyDtos.StrategyResponse first = dispatch("S1", "REQ-R", T0);
82	        StrategyDtos.StrategyResponse replay = dispatch("S1", "REQ-R", T0);
83	        assertThat(replay.requestId()).isEqualTo(first.requestId());
84	        assertThat(replay.effectiveTime()).isEqualTo(first.effectiveTime());
85	        assertThat(strategyRepository.findByCode("S1").orElseThrow().status()).isEqualTo("DISPATCHED");
86	    }
87	
88	    @Test
89	    @DisplayName("同 requestId 不同参数（生效时刻不同）返回 409")
90	    void sameRequestDifferentParamsConflicts() {
91	        draftStrategy("S1", "24.00", "18.00", "70.00", "0.5", "5");
92	        dispatch("S1", "REQ-C", T0);
93	        assertThatThrownBy(() -> dispatch("S1", "REQ-C", T0.plusSeconds(30 * 60)))
94	                .isInstanceOf(ConflictException.class);
95	    }
96	
97	    @Test
98	    @DisplayName("并发下发不同策略到同分区：仅一个 DISPATCHED 生效，另一个被原子替换或拒绝")
99	    void concurrentDispatchSameZoneOnlyOneWins() throws Exception {
100	        draftStrategy("S1", "24.00", "18.00", "70.00", "0.5", "5");
101	        draftStrategy("S2", "25.00", "17.00", "70.00", "0.5", "5");
102	        // 先让 S1 生效，再并发下发 S2/S3（间隔均满足 30 分钟，唯一约束在生效时刻上兜底）。
103	        dispatch("S1", "REQ-INIT", T0);
104	        draftStrategy("S3", "26.00", "18.00", "70.00", "0.5", "5");
105	
106	        Instant target = T0.plusSeconds(30 * 60);
107	        CountDownLatch start = new CountDownLatch(1);
108	        ExecutorService pool = Executors.newFixedThreadPool(2);
109	        try {
110	            List<Future<?>> futures = List.of(
111	                    pool.submit(() -> {
112	                        start.await();
113	                        return dispatch("S2", "REQ-C2", target);
114	                    }),
115	                    pool.submit(() -> {
116	                        start.await();
117	                        return dispatch("S3", "REQ-C3", target);
118	                    }));
119	            start.countDown();
120	            int success = 0;
121	            int conflict = 0;
122	            for (Future<?> f : futures) {
123	                try {
124	                    f.get(15, TimeUnit.SECONDS);
125	                    success++;
126	                } catch (Exception e) {
127	                    conflict++;
128	                }
129	            }
130	            assertThat(success).isEqualTo(1);
131	            assertThat(conflict).isEqualTo(1);
132	            // 同时刻最终只有一个生效策略，且 S1 已失效。
133	            Integer dispatched = jdbcTemplate.queryForObject(
134	                    "SELECT COUNT(1) FROM climate_strategy WHERE zone_code = ? AND status = 'DISPATCHED'",
135	                    Integer.class, ZONE);
136	            assertThat(dispatched).isEqualTo(1);
137	            Integer expiredS1 = jdbcTemplate.queryForObject(
138	                    "SELECT COUNT(1) FROM climate_strategy WHERE strategy_code = 'S1' AND status = 'EXPIRED'",
139	                    Integer.class);
140	            assertThat(expiredS1).isEqualTo(1);
141	        } finally {
142	            pool.shutdownNow();
143	        }
144	    }
145	}
