            if (interval.abs().compareTo(MIN_CHANGE_INTERVAL) < 0) {
                throw new BusinessRuleException("距上次策略变更间隔 " + interval.toMinutes()
                        + " 分钟，少于最小间隔 30 分钟");
            }
        });
