19	class AlarmAckTest extends AbstractIntegrationTest {
20	
21	    private static final Instant T0 = Instant.parse("2026-01-05T02:00:00Z");
22	
23	    @BeforeEach
24	    void setUp() {
25	        seedZone();
26	        seedCrop();
27	        draftStrategy("S1", "24.00", "18.00", "70.00", "1.0", "5.0");
28	        dispatch("S1", "REQ-D", T0.minusSeconds(60));
29	    }
30	
31	    private Long triggerAlarm() {
32	        ingest(T0, "27.00", "70");
33	        ingest(T0.plusSeconds(60), "27.00", "70");
34	        ReadingDtos.ReadingResponse trigger = ingest(T0.plusSeconds(120), "27.00", "70");
35	        return trigger.alarmId();
36	    }
37	
38	    @Test
39	    @DisplayName("确认告警成功后置 ACKNOWLEDGED；同 requestId 重放返回首次结果")
40	    void acknowledgeIsIdempotent() {
41	        Long alarmId = triggerAlarm();
42	        AlarmDtos.AlarmResponse first = alarmService.acknowledge(
43	                new AlarmDtos.AckRequest(alarmId, "ACK-1"));
44	        assertThat(first.status()).isEqualTo("ACKNOWLEDGED");
45	        assertThat(first.ackRequestId()).isEqualTo("ACK-1");
46	
47	        AlarmDtos.AlarmResponse replay = alarmService.acknowledge(
48	                new AlarmDtos.AckRequest(alarmId, "ACK-1"));
49	        assertThat(replay.acknowledgedAt()).isEqualTo(first.acknowledgedAt());
50	        assertThat(alarmService.listActive(ZONE)).isEmpty();
51	    }
52	
53	    @Test
54	    @DisplayName("同 requestId 确认不同告警返回 409")
55	    void sameRequestDifferentAlarmConflicts() {
